-- ACADLYX finance domain
CREATE TABLE "fee_invoice_items" ("id" TEXT NOT NULL,"invoiceId" TEXT NOT NULL,"feeHeadId" TEXT,"description" TEXT NOT NULL,"amount" DECIMAL(14,2) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "fee_invoice_items_pkey" PRIMARY KEY ("id"),CONSTRAINT "fee_invoice_items_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "fee_invoices"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "fee_invoice_items_feeHeadId_fkey" FOREIGN KEY ("feeHeadId") REFERENCES "fee_heads"("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "fee_invoice_items_amount_check" CHECK ("amount" >= 0));
CREATE INDEX "fee_invoice_items_invoiceId_idx" ON "fee_invoice_items"("invoiceId");
CREATE TABLE "fee_concessions" ("id" TEXT NOT NULL,"institutionId" TEXT NOT NULL,"invoiceId" TEXT NOT NULL,"studentId" TEXT NOT NULL,"type" TEXT NOT NULL,"amount" DECIMAL(14,2) NOT NULL,"percentage" DECIMAL(7,4),"reason" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"createdById" TEXT NOT NULL,"approvedById" TEXT,"approvedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "fee_concessions_pkey" PRIMARY KEY ("id"),CONSTRAINT "fee_concessions_institutionId_fkey" FOREIGN KEY ("institutionId") REFERENCES "institutions"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "fee_concessions_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "fee_invoices"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "fee_concessions_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "fee_concessions_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "fee_concessions_approvedById_fkey" FOREIGN KEY ("approvedById") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "fee_concessions_amount_check" CHECK ("amount" >= 0));
CREATE INDEX "fee_concessions_institutionId_studentId_status_idx" ON "fee_concessions"("institutionId","studentId","status"); CREATE INDEX "fee_concessions_invoiceId_idx" ON "fee_concessions"("invoiceId");
CREATE TABLE "fee_refunds" ("id" TEXT NOT NULL,"institutionId" TEXT NOT NULL,"paymentId" TEXT NOT NULL,"invoiceId" TEXT NOT NULL,"studentId" TEXT NOT NULL,"amount" DECIMAL(14,2) NOT NULL,"reason" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'REQUESTED',"requestedById" TEXT NOT NULL,"approvedById" TEXT,"processedById" TEXT,"approvedAt" TIMESTAMP(3),"processedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "fee_refunds_pkey" PRIMARY KEY ("id"),CONSTRAINT "fee_refunds_institutionId_fkey" FOREIGN KEY ("institutionId") REFERENCES "institutions"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "fee_refunds_paymentId_fkey" FOREIGN KEY ("paymentId") REFERENCES "fee_payments"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "fee_refunds_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "fee_invoices"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "fee_refunds_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "fee_refunds_requestedById_fkey" FOREIGN KEY ("requestedById") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "fee_refunds_approvedById_fkey" FOREIGN KEY ("approvedById") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "fee_refunds_processedById_fkey" FOREIGN KEY ("processedById") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "fee_refunds_amount_check" CHECK ("amount" > 0));
CREATE INDEX "fee_refunds_institutionId_status_idx" ON "fee_refunds"("institutionId","status"); CREATE INDEX "fee_refunds_paymentId_idx" ON "fee_refunds"("paymentId"); CREATE INDEX "fee_refunds_invoiceId_idx" ON "fee_refunds"("invoiceId");
CREATE TABLE "fee_transactions" ("id" TEXT NOT NULL,"institutionId" TEXT NOT NULL,"studentId" TEXT,"invoiceId" TEXT,"paymentId" TEXT,"amount" DECIMAL(14,2) NOT NULL,"type" TEXT NOT NULL,"reference" TEXT,"metadata" JSONB,"createdById" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "fee_transactions_pkey" PRIMARY KEY ("id"),CONSTRAINT "fee_transactions_institutionId_fkey" FOREIGN KEY ("institutionId") REFERENCES "institutions"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "fee_transactions_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "fee_transactions_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "fee_invoices"("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "fee_transactions_paymentId_fkey" FOREIGN KEY ("paymentId") REFERENCES "fee_payments"("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "fee_transactions_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "fee_transactions_institutionId_createdAt_idx" ON "fee_transactions"("institutionId","createdAt"); CREATE INDEX "fee_transactions_institutionId_studentId_idx" ON "fee_transactions"("institutionId","studentId"); CREATE INDEX "fee_transactions_institutionId_type_idx" ON "fee_transactions"("institutionId","type");
CREATE TABLE "fee_receipts" ("id" TEXT NOT NULL,"institutionId" TEXT NOT NULL,"paymentId" TEXT NOT NULL,"invoiceId" TEXT NOT NULL,"studentId" TEXT NOT NULL,"receiptNumber" TEXT NOT NULL,"issuedById" TEXT,"issuedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "fee_receipts_pkey" PRIMARY KEY ("id"),CONSTRAINT "fee_receipts_paymentId_key" UNIQUE ("paymentId"),CONSTRAINT "fee_receipts_institutionId_receiptNumber_key" UNIQUE ("institutionId","receiptNumber"),CONSTRAINT "fee_receipts_institutionId_fkey" FOREIGN KEY ("institutionId") REFERENCES "institutions"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "fee_receipts_paymentId_fkey" FOREIGN KEY ("paymentId") REFERENCES "fee_payments"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "fee_receipts_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "fee_invoices"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "fee_receipts_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "fee_receipts_issuedById_fkey" FOREIGN KEY ("issuedById") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "fee_receipts_institutionId_studentId_idx" ON "fee_receipts"("institutionId","studentId");